export function wavHeader(frames,sampleRate=44100,channels=2){const b=new ArrayBuffer(44),d=new DataView(b),text=(p,s)=>{for(let i=0;i<s.length;i++)d.setUint8(p+i,s.charCodeAt(i))};text(0,'RIFF');d.setUint32(4,36+frames*channels*2,true);text(8,'WAVE');text(12,'fmt ');d.setUint32(16,16,true);d.setUint16(20,1,true);d.setUint16(22,channels,true);d.setUint32(24,sampleRate,true);d.setUint32(28,sampleRate*channels*2,true);d.setUint16(32,channels*2,true);d.setUint16(34,16,true);text(36,'data');d.setUint32(40,frames*channels*2,true);return b}
export function pcm16(samples){const out=new Int16Array(samples.length);for(let i=0;i<samples.length;i++){const n=Math.max(-1,Math.min(1,samples[i]));out[i]=n<0?Math.round(n*32768):Math.round(n*32767)}return out}
export function encodeWav(samples,rate=44100,channels=2){const data=pcm16(samples),out=new Uint8Array(44+data.byteLength);out.set(new Uint8Array(wavHeader(samples.length/channels,rate,channels)));out.set(new Uint8Array(data.buffer),44);return out.buffer}
export function decodeWav(buffer){const d=new DataView(buffer);if(d.getUint32(0)!==0x52494646||d.getUint32(8)!==0x57415645)throw Error('Invalid WAV');let p=12,rate,channels,bits,format;while(p+8<=buffer.byteLength){const id=d.getUint32(p),size=d.getUint32(p+4,true);if(id===0x666d7420){format=d.getUint16(p+8,true);channels=d.getUint16(p+10,true);rate=d.getUint32(p+12,true);bits=d.getUint16(p+22,true)}if(id===0x64617461){if(format!==1||bits!==16)throw Error('Expected PCM16 WAV');const samples=new Float32Array(size/2);for(let i=0;i<samples.length;i++)samples[i]=d.getInt16(p+8+i*2,true)/32768;return{samples,rate,channels}}p+=8+size+(size%2)}throw Error('WAV has no audio')}
